source "$(dirname "$0")/lib/assert.sh"
H="$KF_ROOT/plugins/core-governance/hooks/ngvu_guardrails.py"
out=$(python -I "$H" --self-test 2>&1); assert_eq 0 "$?" "hook self-test: $out"
hook() { printf '{"tool_name":"%s","tool_input":{"command":%s}}' "$1" "$(python -I -c 'import json,sys; print(json.dumps(sys.argv[1]))' "$2")" | python -I "$H" >/dev/null 2>&1; echo $?; }
assert_eq 0 "$(hook Bash 'git -C D:/workspace/services/example_core push -u origin ngvu/vung-1-x')" "allows the ticket-branch push the factory runs (2026-10-27)"
assert_eq 2 "$(hook Bash 'git -C D:/workspace/services/example_core push origin HEAD:master')" "blocks a refspec push to master (2026-10-27)"
assert_eq 2 "$(hook Bash 'git push --force origin ngvu/vung-1-x')" "blocks a force push of a ticket branch (2026-10-27)"
assert_eq 0 "$(hook Bash "grep -rn 'git push origin master' docs")" "a grep pattern mentioning a push is data (2026-10-27)"
assert_eq 2 "$(hook PowerShell 'git push origin master')" "blocks a push through PowerShell"
assert_eq 2 "$(hook Bash 'acli jira workitem transition --key VUNG-1 --status Done')" "blocks an acli Jira write"
assert_eq 0 "$(hook Bash 'git -C D:/workspace/services/example_core fetch -q origin')" "allows fetch"
assert_eq 0 "$(hook Bash 'git worktree add -q --no-track -b b D:/wt origin/master')" "allows worktree creation"
assert_eq 2 "$(printf 'not json git push' | python -I "$H" >/dev/null 2>&1; echo $?)" "unreadable input mentioning git push is blocked"
assert_eq 0 "$(hook Bash $'git commit -q -F - <<\'EOF\'\n- blocks every git push (incl. git -C <repo> push),\nEOF')" "a commit message heredoc mentioning a push is allowed (0.5.1)"
assert_eq 0 "$(hook Bash 'git commit -m "fix git push bug"')" "a -m message mentioning a push is allowed (0.5.1)"
assert_eq 2 "$(hook Bash $'git commit -F - <<\'EOF\'\nmsg\nEOF\ngit push origin b')" "a push after the message heredoc is still blocked (0.5.1)"
assert_eq 2 "$(hook Bash $'bash <<\'EOF\'\ngit push\nEOF')" "a heredoc fed to a shell is still checked (0.5.1)"
assert_eq 2 "$(hook Bash 'git commit -m "$(git push)"')" "a command substitution inside a message is still checked (0.5.1)"
kf_finish
